<?php declare(strict_types=1); namespace App\Infrastructure\Persistence\Doctrine\Arena; use App\Domain\Arena\Repository\DuelAnswerVerifierInterface;use App\Infrastructure\Persistence\Doctrine\Arena\Entity\DuelQuestionRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionOptionRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;use Doctrine\ORM\EntityManagerInterface;final class DoctrineDuelAnswerVerifier implements DuelAnswerVerifierInterface { public function __construct(private readonly EntityManagerInterface $em){}public function verify(string $duelId,int $position,string $optionId):?bool{$q=$this->em->find(DuelQuestionRecord::class,['duelId'=>$duelId,'position'=>$position]);if(!$q instanceof DuelQuestionRecord)return null;$question=$this->em->find(QuestionRecord::class,$q->questionId);$option=$this->em->find(QuestionOptionRecord::class,$optionId);if(!$question instanceof QuestionRecord||!$option instanceof QuestionOptionRecord||$option->questionId!==$q->questionId||$question->correctOptionId===null)return null;return hash_equals($question->correctOptionId,$optionId);}}
